PTX_SOURCE = r'''
.version 8.0
.target sm_80
.address_size 64

.visible .entry tanh_kernel(
    .param .u64 __cudaptr_input,
    .param .u64 __cudaptr_output,
    .param .u64 __cudaptr_N
)
{
    // registers
    .reg .pred   %p<2>;
    .reg .b64    %rd<9>;
    .reg .b32    %r<5>;
    .reg .f32    %f<2>;
    .reg .f16    %h<2>;

    // load kernel parameters
    ld.param.u64    %rd1, [__cudaptr_input];
    ld.param.u64    %rd2, [__cudaptr_output];
    ld.param.u64    %rd3, [__cudaptr_N];        // total elements N

    // compute thread id: idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32         %r1, %ctaid.x;
    mov.u32         %r2, %ntid.x;
    mul.lo.u32      %r3, %r1, %r2;              // blockIdx.x * blockDim.x
    add.u32         %r4, %r3, %tid.x;           // + threadIdx.x
    cvt.u64.u32     %rd4, %r4;                  // idx (64‑bit)

    // compute stride = gridDim.x * blockDim.x
    mov.u32         %r5, %nctaid.x;
    mul.lo.u32      %r5, %r5, %ntid.x;          // gridDim.x * blockDim.x
    cvt.u64.u32     %rd5, %r5;                  // stride (64‑bit)

    // early exit if idx >= N
    setp.ge.u64     %p0, %rd4, %rd3;
    @%p0 bra        DONE;

LOOP:
    // byte offset for current element (half = 2 bytes)
    mul.wide.u64    %rd6, %rd4, 2;              // offset = idx * 2

    // load fp16 value
    ld.global.f16   %h1, [%rd1 + %rd6];

    // convert to fp32, compute tanh, convert back to fp16
    cvt.rn.f32      %f1, %h1;
    tanh.approx.f32 %f1, %f1;
    cvt.rn.f16      %h2, %f1;

    // store result
    st.global.f16   [%rd2 + %rd6], %h2;

    // idx += stride
    add.u64         %rd4, %rd4, %rd5;

    // continue while idx < N
    setp.lt.u64     %p0, %rd4, %rd3;
    @%p0 bra        LOOP;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Model wrapper that launches the PTX kernel
# ----------------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew:
    def __init__(self):
        # launch configuration
        self.block_size = 256
        # load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        # ensure input is half‑precision and on CUDA
        x_fp16 = x.to(dtype=torch.float16, device='cuda')
        # allocate output tensor
        out = torch.empty_like(x_fp16, dtype=torch.float16, device='cuda')
        # total number of elements
        N = x_fp16.numel()
        # grid dimensions
        grid_x = (N + self.block_size - 1) // self.block_size
        grid = (grid_x, 1, 1)
        block = (self.block_size, 1, 1)
        # kernel arguments: input ptr, output ptr, N
        args = [x_fp16.data_ptr(), out.data_ptr(), N]
